[IO.File]::WriteAllText((Join-Path $PWD 'suite.conf'), "# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.`n# The suite: one config for any server. The host, port and token come from the environment;`n# the host defaults to 127.0.0.1 when SURL_HOST is not set.`nvariable = %SURL_HOST=127.0.0.1`nvariable = %SURL_PORT`nvariable = %API_TOKEN`n`nsilent`nshow-error`nfail`nwrite-out = `"%{url.path} %{http_code}\n`"`nexpand-oauth2-bearer = `"{{API_TOKEN:trim}}`"`n`nexpand-url = `"http://{{SURL_HOST}}:{{SURL_PORT:trim}}/health.txt`"`nout-null`nexpand-url = `"http://{{SURL_HOST}}:{{SURL_PORT:trim}}/report.csv`"`nout-null`n")
